/** Prix au kilo des colis selon la zone du pays : Afrique 5 000 FCFA, Europe et Amérique 10 000 FCFA. */
function tdg_prix_kg_zone( $zone ) {
	return 'afrique' === $zone ? 5000 : 10000;
}

/** Trajets par défaut : du Burkina vers chaque pays et retour, avec le prix au kilo de la zone. */
function tdg_trajets_defaut() {
	$connus = array(
		'BF-FR' => array( '7 à 12 jours', 'Aérien groupé' ),
		'FR-BF' => array( '7 à 12 jours', 'Aérien groupé' ),
		'BF-US' => array( '10 à 15 jours', 'Aérien groupé' ),
		'US-BF' => array( '10 à 15 jours', 'Aérien groupé' ),
		'BF-CI' => array( '4 à 6 jours', 'Routier' ),
	);
	$t = array();
	foreach ( tdg_pays() as $code => $p ) {
		if ( 'BF' === $code ) {
			continue;
		}
		foreach ( array( 'BF-' . $code, $code . '-BF' ) as $cle ) {
			$t[ $cle ] = array(
				'actif'   => 1,
				'delai'   => isset( $connus[ $cle ] ) ? $connus[ $cle ][0] : 'À confirmer',
				'mode'    => isset( $connus[ $cle ] ) ? $connus[ $cle ][1] : ( 'afrique' === $p['zone'] ? 'Aérien ou routier' : 'Aérien groupé' ),
				'prix_kg' => tdg_prix_kg_zone( $p['zone'] ),
			);
		}
	}
	return $t;
}

/** Lieux de dépôt par défaut. */
function tdg_agences_defaut() {
	$a = array(
		'BF' => 'Agence Tondraaga — Ouagadougou',
		'FR' => 'Point de dépôt Paris (partenaire à définir)',
		'US' => 'Point de dépôt New York (partenaire à définir)',
	);
	foreach ( tdg_pays() as $code => $p ) {
		if ( ! isset( $a[ $code ] ) ) {
			$a[ $code ] = 'Point de dépôt ' . $p['nom'] . ' : à confirmer avec notre équipe (WhatsApp)';
		}
	}
	return $a;
}

